-- DETER (alertas de desmatamento do INPE, Amazonia e Cerrado) como ESPELHO VERSIONADO: vetorial.deter_alertas. Idempotente.
-- Rodar como postgres (o etl so tem DML):
--   .\infra\scripts\dw.ps1 psql -Arquivo deter\alertas\sql\01_tabela.sql
--
-- Regras (as mesmas do SICAR, do PRODES, do MapBiomas Alerta e da FUNAI): a tabela espelha o que o servidor publica hoje; cada alerta
-- (id_bioma, gid, chave_linha) tem versoes (vigente_desde/vigente_ate); alerta que o servidor deixa de publicar tem a versao FECHADA (nada e apagado na
-- coleta); alerta que some e volta IDENTICO tem a versao reaberta. Colunas com os nomes da fonte; texto sempre `text`.
-- ATENCAO: o gid NAO identifica o poligono (na Amazonia o mesmo gid, ex. 17641_hist, e reutilizado por alertas de anos, municipios e classes
-- diferentes) e nenhum outro campo isolado e unico. A chave da linha e composta (chave_linha). Ver LEIAME_deter_alertas.md.
-- Uma tabela para os dois biomas (mesma fonte e mesma metodologia); colunas que so um bioma publica ficam NULL no outro.

CREATE TABLE IF NOT EXISTS vetorial.deter_alertas (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_bioma          smallint    NOT NULL REFERENCES dim.biomas (id_bioma),   -- derivado da camada de origem (1 Amazonia, 3 Cerrado)
    gid               text        NOT NULL,                  -- fonte: gid (NAO e unico: repetido entre alertas e entre municipios; sufixo _hist = historico consolidado, _curr = mes corrente)
    chave_linha       text        NOT NULL,                  -- derivado: municipio|view_date|classname|areamunkm; com id_bioma e gid identifica a linha (a fonte nao traz identificador unico)
    classname         text,                                  -- fonte: classname (DESMATAMENTO_CR, DESMATAMENTO_VEG, MINERACAO, CICATRIZ_DE_QUEIMADA, CS_DESORDENADO...)
    quadrant          text,                                  -- fonte: quadrant (quadrante da cena, quando houver)
    path_row          text,                                  -- fonte: path_row (orbita/ponto da cena)
    view_date         date,                                  -- fonte: view_date (data da imagem em que o alerta foi visto)
    created_date      date,                                  -- fonte: created_date (so Cerrado)
    sensor            text,                                  -- fonte: sensor
    satellite         text,                                  -- fonte: satellite
    areatotalkm       double precision,                      -- fonte: areatotalkm (km2; so Cerrado)
    areauckm          double precision,                      -- fonte: areauckm (km2 dentro de unidade de conservacao)
    uc                text,                                  -- fonte: uc (unidade de conservacao, quando houver)
    areamunkm         double precision,                      -- fonte: areamunkm (km2 dentro do municipio)
    municipality      text,                                  -- fonte: municipality (nome, como entregue)
    mun_geocod        text,                                  -- fonte: mun_geocod (codigo IBGE do municipio; so Amazonia)
    uf                text,                                  -- fonte: uf (sigla)
    id_estado         smallint REFERENCES dim.estados (id_estado),            -- derivado de uf
    id_municipio      integer,                               -- derivado de mun_geocod (codigo IBGE); NULL no Cerrado (a fonte so traz o nome)
    publish_month     date,                                  -- fonte: publish_month (mes de publicacao, dia 1)
    geom              geometry(MultiPolygon, 4674),          -- fonte: geometria (SIRGAS 2000). NULL quando geom_anomala
    geom_anomala      boolean     NOT NULL DEFAULT false,
    geom_origem_texto text,
    id_fonte          smallint    NOT NULL REFERENCES dim.fontes (id_fonte),
    importado_em      date        NOT NULL DEFAULT current_date,
    vigente_desde     date        NOT NULL DEFAULT current_date,
    vigente_ate       date,
    coletado_em       timestamptz NOT NULL DEFAULT now(),
    reaberto_em       date
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_deter_alertas_vigente ON vetorial.deter_alertas (id_bioma, gid, chave_linha) WHERE vigente_ate IS NULL;
-- Indices secundarios: criados depois da primeira carga (carregar com eles e mais lento); IF NOT EXISTS deixa reaplicar.
CREATE INDEX IF NOT EXISTS ix_deter_alertas_geom  ON vetorial.deter_alertas USING gist (geom) WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_deter_alertas_data  ON vetorial.deter_alertas (view_date) WHERE vigente_ate IS NULL;
CREATE INDEX IF NOT EXISTS ix_deter_alertas_uf    ON vetorial.deter_alertas (id_estado, id_bioma) WHERE vigente_ate IS NULL;

COMMENT ON TABLE vetorial.deter_alertas IS
    'DETER (INPE): alertas de desmatamento e degradacao quase em tempo real, Amazonia e Cerrado, espelho do servidor de mapas do TerraBrasilis. Espelho versionado: vigente = vigente_ate IS NULL. Ver deter/alertas/LEIAME_deter_alertas.md.';
COMMENT ON COLUMN vetorial.deter_alertas.gid IS 'Origem: gid. NAO e unico: a fonte repete o gid entre municipios que o poligono cruza e o reutiliza para alertas diferentes (anos, municipios e classes distintos). Use chave_linha para a identidade da linha.';
COMMENT ON COLUMN vetorial.deter_alertas.chave_linha IS 'Derivado: municipio (mun_geocod ou nome em maiusculas) | view_date | classname | areamunkm. Com id_bioma e gid identifica a linha: a fonte nao traz identificador unico e o gid se repete.';
COMMENT ON COLUMN vetorial.deter_alertas.classname IS 'Origem: classname. Classe do alerta; DETER e um sistema de ALERTA (nao e o dado oficial de desmatamento, que e o PRODES).';
COMMENT ON COLUMN vetorial.deter_alertas.id_estado IS 'Derivado de uf (dim.estados).';
COMMENT ON COLUMN vetorial.deter_alertas.id_municipio IS 'Derivado de mun_geocod (codigo IBGE do municipio); NULL no Cerrado, onde a fonte so traz o nome.';

