GRANT SELECT, INSERT, UPDATE, DELETE ON vetorial.deter_alertas TO etl;      -- DELETE: so para a rotina de retencao
GRANT SELECT ON vetorial.deter_alertas TO leitura, geoserver, analistas;
GRANT MAINTAIN ON vetorial.deter_alertas TO etl;

SELECT 'vetorial.deter_alertas' AS item, count(*)::text AS valor FROM vetorial.deter_alertas;
